//! Psalms (Zabur) resolver.
//!
//! Reads `psalms/{psalm}.json`, one file per psalm, generated by
//! `scripts/build-psalms.py` from eBible.org's public-domain exports: the
//! Smith & Van Dyck Arabic (1865) as `ar`, the King James Version as `en`, and
//! the World English Bible beside it as `en_web`. Search matches `ar` and
//! `en`, as for every other source; `en_web` is returned, not searched.
//!
//! # Versification
//!
//! All three texts number verses the English way, where a psalm's title — "A
//! Psalm of David" — opens verse 1 rather than standing as a verse of its own.
//! Hebrew-numbered editions count the title separately, so Psalm 51 has 19
//! verses here and 21 there, and a citation taken from one of them can be a
//! verse or two off wherever a psalm carries a title.
//!
//! # Why only Psalms
//!
//! Psalms is a single book, so it fits the grammar as it stands: `PS:23:1` is
//! Psalm 23, verse 1, and `PS::N` counts verses across the whole book. The
//! Torah and the rest of the Bible need a third level — book, chapter, verse —
//! which the grammar does not have, so they are not carried.

use crate::ast::Reference;
use crate::error::Error;
use crate::record::Record;
use crate::repo::Repository;
use crate::sources::{locate, total, Source};
use serde::Deserialize;
use std::sync::Arc;

const PSALM_COUNT: u32 = 150;
const DIR: &str = "psalms";

/// Verse count of each psalm, in the English versification all three texts
/// share. Lets `PS::N` find its psalm without reading the other 149 files; a
/// test checks every entry against the data.
const PSALM_VERSES: [u32; PSALM_COUNT as usize] = [
    6, 12, 8, 8, 12, 10, 17, 9, 20, 18, 7, 8, 6, 7, 5, 11, 15, 50, 14, 9, 13, 31, 6, 10, 22, 12,
    14, 9, 11, 12, 24, 11, 22, 22, 28, 12, 40, 22, 13, 17, 13, 11, 5, 26, 17, 11, 9, 14, 20, 23,
    19, 9, 6, 7, 23, 13, 11, 11, 17, 12, 8, 12, 11, 10, 13, 20, 7, 35, 36, 5, 24, 20, 28, 23, 10,
    12, 20, 72, 13, 19, 16, 8, 18, 12, 13, 17, 7, 18, 52, 17, 16, 15, 5, 23, 11, 13, 12, 9, 9, 5,
    8, 28, 22, 35, 45, 48, 43, 13, 31, 7, 10, 10, 9, 8, 18, 19, 2, 29, 176, 7, 8, 9, 4, 8, 5, 6, 5,
    6, 8, 8, 3, 18, 3, 3, 21, 26, 9, 8, 24, 13, 10, 7, 12, 15, 21, 10, 20, 14, 9, 6,
];

/// Verses in the whole book. Derived, so it cannot drift from the table.
const VERSE_COUNT: u32 = total(&PSALM_VERSES);

/// `PS` — the Psalms of David, the Zabur.
#[derive(Debug, Default)]
pub struct Psalms;

#[derive(Debug, Deserialize)]
struct Psalm {
    verses: Vec<Verse>,
}

#[derive(Debug, Deserialize)]
struct Verse {
    verse: u32,
    ar: String,
    kjv: String,
    web: String,
}

impl Source for Psalms {
    fn code(&self) -> &str {
        "PS"
    }

    fn name(&self) -> &str {
        "Psalms (Zabur)"
    }

    fn aliases(&self) -> Vec<&str> {
        vec!["ZABUR", "PSALMS"]
    }

    fn total(&self, _repo: &mut Repository) -> Result<Option<u32>, Error> {
        Ok(Some(VERSE_COUNT))
    }

    fn resolve(
        &self,
        repo: &mut Repository,
        reference: &Reference,
        out: &mut Vec<Record>,
    ) -> Result<(), Error> {
        // `PS::100` — count verses across the whole book.
        let Some(number) = reference.primary else {
            return self.resolve_flat(repo, reference, out);
        };

        if number == 0 || number > PSALM_COUNT {
            return Err(Error::ReferenceNotFound {
                detail: format!("Psalm {number} (Psalms has 1..=150)"),
            });
        }

        let psalm = Self::load(repo, number)?;
        let count = u32::try_from(psalm.verses.len()).map_err(|_| Error::InvalidDataFile {
            path: format!("{DIR}/{number}.json"),
            detail: "implausible verse count".into(),
        })?;

        for verse in reference.expand(count)? {
            out.push(self.record(&psalm, number, verse)?);
        }

        Ok(())
    }
}

impl Psalms {
    fn load(repo: &mut Repository, number: u32) -> Result<Arc<Psalm>, Error> {
        repo.load(format!("{DIR}/{number}.json"))
    }

    /// One verse as a record. Files are ordered and complete, but the verse is
    /// found by its number rather than trusted to its position.
    fn record(&self, psalm: &Psalm, number: u32, verse: u32) -> Result<Record, Error> {
        let found = psalm
            .verses
            .iter()
            .find(|v| v.verse == verse)
            .ok_or_else(|| Error::ReferenceNotFound {
                detail: format!("PS:{number}:{verse}"),
            })?;

        Ok(Record {
            source: self.code().to_string(),
            collection: self.name().to_string(),
            extra: [
                ("psalm".to_string(), number.into()),
                ("verse".to_string(), verse.into()),
                ("en_web".to_string(), found.web.clone().into()),
            ]
            .into_iter()
            .collect(),
            ar: found.ar.clone(),
            emlaei: String::new(),
            en: found.kjv.clone(),
        })
    }

    /// `PS::N` — the N-th verse of the book, 1..=2461, read from the ordinary
    /// psalm files so it is the same text `PS:psalm:verse` returns.
    fn resolve_flat(
        &self,
        repo: &mut Repository,
        reference: &Reference,
        out: &mut Vec<Record>,
    ) -> Result<(), Error> {
        for global in reference.expand(VERSE_COUNT)? {
            let (number, verse) =
                locate(&PSALM_VERSES, global).ok_or_else(|| Error::ReferenceNotFound {
                    detail: format!("PS::{global}"),
                })?;

            let psalm = Self::load(repo, number)?;
            let mut record = self.record(&psalm, number, verse)?;
            record.extra.insert("number".to_string(), global.into());
            record.extra.insert("numbering".to_string(), "book".into());
            out.push(record);
        }

        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_table_covers_the_whole_book() {
        assert_eq!(PSALM_VERSES.len(), 150);
        assert_eq!(VERSE_COUNT, 2461);
        // The longest and the shortest.
        assert_eq!(PSALM_VERSES[118], 176);
        assert_eq!(PSALM_VERSES[116], 2);
    }

    #[test]
    fn locate_maps_the_edges_of_the_book() {
        assert_eq!(locate(&PSALM_VERSES, 1), Some((1, 1)));
        assert_eq!(locate(&PSALM_VERSES, 6), Some((1, 6)));
        assert_eq!(locate(&PSALM_VERSES, 7), Some((2, 1)));
        assert_eq!(locate(&PSALM_VERSES, VERSE_COUNT), Some((150, 6)));
        assert_eq!(locate(&PSALM_VERSES, VERSE_COUNT + 1), None);
        assert_eq!(locate(&PSALM_VERSES, 0), None);
    }
}
